)

const cacheSizeLimit = 100

type HTTPClient struct {
	cache SimpleCache[string]
	hc    httpDoer
	ttl   time.Duration
}

type httpDoer interface {
	Do(req *http.Request) (*http.Response, error)
}

type requestData struct {
	Method string
	Header http.Header
	URL    string
	Body   *string
}

func NewHTTPClient(wrapped httpDoer, ttl time.Duration) *HTTPClient {
	return &HTTPClient{
		hc:    wrapped,
		ttl:   ttl,
		cache: newSimpleCacheWithCapacity[string](cacheSizeLimit),
	}
}

func newSimpleCacheWithCapacity[V any](capacity int) SimpleCache[V] {
	return newSimpleCache[V](capacity)
}

func (c *HTTPClient) loadResponse(key string) (string, time.Duration, error) {
		req, err := c.deserializeReq(key)
		if err != nil {
			return "", 0, err
		}
		resp, err := c.hc.Do(req)
		if err != nil {
			return "", 0, err
		}
		defer resp.Body.Close()
		response := c.serializeResponse(resp)
		log.Trace("New request cached", "req", key, "resp", response)
		return response, c.ttl, nil
}

func (c *HTTPClient) Do(req *http.Request) (*http.Response, error) {
	key := c.serializeReq(req)
	respStr, err := c.cache.GetWithLoader(key, c.loadResponse)
	if err != nil {
		return nil, err
	}
	return c.deserializeResponse(req, respStr)
}

func (c *HTTPClient) serializeReq(req *http.Request) string {
	data := requestData{
		Method: req.Method,
		Header: req.Header,
		URL:    req.URL.String(),
	}
	if req.Body != nil {
		bodyData, _ := io.ReadAll(req.Body)
		bodyStr := base64.StdEncoding.EncodeToString(bodyData)
		data.Body = &bodyStr
	}
	j, _ := json.Marshal(&data)
	return string(j)
}

func (c *HTTPClient) deserializeReq(reqStr string) (*http.Request, error) {
	var data requestData
	_ = json.Unmarshal([]byte(reqStr), &data)
	var body io.Reader
	if data.Body != nil {
		bodyStr, _ := base64.StdEncoding.DecodeString(*data.Body)
		body = strings.NewReader(string(bodyStr))
	}
	req, err := http.NewRequest(data.Method, data.URL, body)
	if err != nil {
		return nil, err
	}
	req.Header = data.Header
	return req, nil
}

func (c *HTTPClient) serializeResponse(resp *http.Response) string {
	var b = &bytes.Buffer{}
	_ = resp.Write(b)
	return b.String()
}

func (c *HTTPClient) deserializeResponse(req *http.Request, respStr string) (*http.Response, error) {
	r := bufio.NewReader(strings.NewReader(respStr))
	return http.ReadResponse(r, req)
}
package cache

import (
	"errors"
	"sync"
	"time"
)

// ErrCacheMiss is returned when a key is not present or its TTL has elapsed.
var ErrCacheMiss = errors.New("cache: key not found")

// SimpleCache is a typed cache with optional per-entry expiration.
type SimpleCache[V any] interface {
	Add(key string, value V) error
	AddWithTTL(key string, value V, ttl time.Duration) error
	Get(key string) (V, error)
	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)
	Keys() []string
}

// NewSimpleCache creates an unbounded cache whose entries do not expire unless
// they are added with AddWithTTL.
func NewSimpleCache[V any]() SimpleCache[V] {
	return newSimpleCache[V](0)
}

type simpleCache[V any] struct {
	mu         sync.Mutex
	items      map[string]cacheEntry[V]
	loads      map[string]*cacheLoad[V]
	maxEntries int
	sequence   uint64
}

type cacheEntry[V any] struct {
	value      V
	expiresAt  time.Time
	lastAccess uint64
}

type cacheLoad[V any] struct {
	done  chan struct{}
	value V
	err   error
}

func newSimpleCache[V any](maxEntries int) SimpleCache[V] {
	return &simpleCache[V]{
		items:      make(map[string]cacheEntry[V]),
		loads:      make(map[string]*cacheLoad[V]),
		maxEntries: maxEntries,
	}
}

func (c *simpleCache[V]) Add(key string, value V) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.storeLocked(key, value, time.Time{})
	return nil
}

func (c *simpleCache[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.storeLocked(key, value, time.Now().Add(ttl))
	return nil
}

func (c *simpleCache[V]) Get(key string) (V, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.getLocked(key, time.Now())
}

func (c *simpleCache[V]) GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error) {
	if value, err := c.Get(key); err == nil {
		return value, nil
	}

	c.mu.Lock()
	if value, err := c.getLocked(key, time.Now()); err == nil {
		c.mu.Unlock()
		return value, nil
	}
	if load, ok := c.loads[key]; ok {
		c.mu.Unlock()
		<-load.done
		return load.value, load.err
	}
	load := &cacheLoad[V]{done: make(chan struct{})}
	c.loads[key] = load
	c.mu.Unlock()

	value, ttl, err := loader(key)

	c.mu.Lock()
	if err == nil {
		// An explicit Add may have populated this key while the loader ran.
		if cached, cacheErr := c.getLocked(key, time.Now()); cacheErr == nil {
			value = cached
		} else {
			c.storeLocked(key, value, time.Now().Add(ttl))
		}
	}
	load.value = value
	load.err = err
	delete(c.loads, key)
	close(load.done)
	c.mu.Unlock()

	return value, err
}

func (c *simpleCache[V]) Keys() []string {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	keys := make([]string, 0, len(c.items))
	for key, entry := range c.items {
		if isExpired(entry, now) {
			delete(c.items, key)
			continue
		}
		keys = append(keys, key)
	}
	return keys
}

func (c *simpleCache[V]) getLocked(key string, now time.Time) (V, error) {
	entry, ok := c.items[key]
	if !ok || isExpired(entry, now) {
		delete(c.items, key)
		var zero V
		return zero, ErrCacheMiss
	}
	c.sequence++
	entry.lastAccess = c.sequence
	c.items[key] = entry
	return entry.value, nil
}

func (c *simpleCache[V]) storeLocked(key string, value V, expiresAt time.Time) {
	now := time.Now()
	if c.maxEntries > 0 {
		for existingKey, entry := range c.items {
			if isExpired(entry, now) {
				delete(c.items, existingKey)
			}
		}
		if _, exists := c.items[key]; !exists && len(c.items) >= c.maxEntries {
			var oldestKey string
			var oldestAccess uint64
			first := true
			for existingKey, entry := range c.items {
				if first || entry.lastAccess < oldestAccess {
					oldestKey = existingKey
					oldestAccess = entry.lastAccess
					first = false
				}
			}
			delete(c.items, oldestKey)
		}
	}
	c.sequence++
	c.items[key] = cacheEntry[V]{
		value:      value,
		expiresAt:  expiresAt,
		lastAccess: c.sequence,
	}
}

func isExpired[V any](entry cacheEntry[V], now time.Time) bool {
	return !entry.expiresAt.IsZero() && !now.Before(entry.expiresAt)
}

